package com.lojaroupas.enums;

public enum FormaPagamento {
    PIX {
        @Override
        public Double calcularAjuste(Double total, Integer parcelas) {
            return total * -0.05;
        }

        @Override
        public boolean validaParcelamento(Integer parcelas) {
            return parcelas == 1;
        }

        @Override
        public boolean validaParaPedido(Double total) {
            return true;
        }

        @Override
        public Double calcularValorParcela(Double total, Integer parcelas) {
            return total - (total * 0.05);
        }
    },
    CARTAO {
        @Override
        public Double calcularAjuste(Double total, Integer parcelas) {
            if (parcelas <= 3) {
                return 0.0;
            }
            Double taxaMensal = 0.0199;
            Double parcela = total * taxaMensal / (1.0 - Math.pow(1.0 + taxaMensal, -parcelas));
            return (parcela * parcelas) - total;
        }

        @Override
        public boolean validaParcelamento(Integer parcelas) {
            return parcelas >= 1 && parcelas <= 12;
        }

        @Override
        public boolean validaParaPedido(Double total) {
            return true;
        }

        @Override
        public Double calcularValorParcela(Double total, Integer parcelas) {
            if (parcelas <= 3) {
                return total / parcelas;
            }
