6	public enum FormaPagamento {
7	    PIX {
8	        @Override
9	        public boolean validaParcelamento(Integer parcelas) {
10	            return parcelas == 1;
11	        }
12	
13	        @Override
14	        public boolean validaParaPedido(Double total) {
15	            return true;
16	        }
17	
18	        @Override
19	        public Double calcularTotalFinal(Double totalBase, Integer parcelas) {
20	            BigDecimal base = new BigDecimal(totalBase);
21	            BigDecimal desconto = base.multiply(new BigDecimal("0.05"));
22	            BigDecimal total = base.subtract(desconto);
23	            return total.setScale(2, RoundingMode.HALF_EVEN).doubleValue();
24	        }
25	
26	        @Override
27	        public Double calcularValorParcela(Double totalFinal, Integer parcelas) {
28	            return totalFinal;
29	        }
30	    },
31	    CARTAO {
32	        @Override
33	        public boolean validaParcelamento(Integer parcelas) {
34	            return parcelas >= 1 && parcelas <= 12;
35	        }
36	
37	        @Override
38	        public boolean validaParaPedido(Double total) {
39	            return true;
40	        }
41	
42	        @Override
43	        public Double calcularTotalFinal(Double totalBase, Integer parcelas) {
44	            if (parcelas <= 3) {
45	                return totalBase;
46	            }
47	            Double taxaMensal = 0.0199;
48	            Double parcela = totalBase * taxaMensal / (1.0 - Math.pow(1.0 + taxaMensal, -parcelas));
49	            BigDecimal parcelaBD = new BigDecimal(parcela);
50	            BigDecimal parcelaArredondada = parcelaBD.setScale(2, RoundingMode.HALF_EVEN);
51	            BigDecimal totalFinal = parcelaArredondada.multiply(new BigDecimal(parcelas));
52	            return totalFinal.doubleValue();
53	        }
54	
55	        @Override
56	        public Double calcularValorParcela(Double totalFinal, Integer parcelas) {
57	            BigDecimal total = new BigDecimal(totalFinal);
58	            BigDecimal parcelaBD = total.divide(new BigDecimal(parcelas), 2, RoundingMode.HALF_EVEN);
59	            return parcelaBD.doubleValue();
60	        }
61	    },
62	    BOLETO {
63	        @Override
64	        public boolean validaParcelamento(Integer parcelas) {
65	            return parcelas == 1;
66	        }
67	
68	        @Override
69	        public boolean validaParaPedido(Double total) {
70	            return total <= 1000.00;
71	        }
72	
73	        @Override
74	        public Double calcularTotalFinal(Double totalBase, Integer parcelas) {
75	            BigDecimal base = new BigDecimal(totalBase);
76	            BigDecimal tarifa = new BigDecimal("3.49");
77	            BigDecimal total = base.add(tarifa);
78	            return total.setScale(2, RoundingMode.HALF_EVEN).doubleValue();
79	        }
80	
81	        @Override
82	        public Double calcularValorParcela(Double totalFinal, Integer parcelas) {
83	            return totalFinal;
84	        }
