1	package com.lojaroupas.validador;
2	
3	import com.lojaroupas.dto.ItemCarrinho;
4	import com.lojaroupas.dto.RequisicaoCheckout;
5	import com.lojaroupas.enums.Cupom;
6	import com.lojaroupas.enums.FormaPagamento;
7	import com.lojaroupas.enums.ModalidadeEntrega;
8	import com.lojaroupas.enums.NivelClube;
9	import com.lojaroupas.enums.Regiao;
10	
11	public class ValidadorRequisicao {
12	
13	    public String validar(RequisicaoCheckout req) {
14	        String erro = validarItens(req);
15	        if (erro != null) return erro;
16	
17	        erro = validarNivelClube(req);
18	        if (erro != null) return erro;
19	
20	        erro = validarRegiao(req);
21	        if (erro != null) return erro;
22	
23	        Double pesoTotal = calcularPesoTotal(req);
24	        erro = validarModalidadeEntrega(req, pesoTotal);
25	        if (erro != null) return erro;
26	
27	        Double subtotal = calcularSubtotal(req);
28	        erro = validarCupom(req, subtotal);
29	        if (erro != null) return erro;
30	
31	        erro = validarFormaPagamento(req);
32	        if (erro != null) return erro;
33	
34	        erro = validarParcelamento(req);
35	        if (erro != null) return erro;
36	
37	        erro = validarDisponibilidadeFormaPagamento(req);
38	        if (erro != null) return erro;
39	
40	        return null;
41	    }
42	
43	    private String validarItens(RequisicaoCheckout req) {
44	        if (req.itens == null || req.itens.isEmpty()) {
45	            return "PEDIDO_INVALIDO";
46	        }
47	
48	        for (ItemCarrinho item : req.itens) {
49	            if (item.precoUnitario == null || item.precoUnitario <= 0 ||
50	                item.quantidade == null || item.quantidade <= 0 ||
51	                item.pesoKg == null || item.pesoKg <= 0) {
52	                return "PEDIDO_INVALIDO";
53	            }
54	        }
55	
56	        return null;
57	    }
58	
59	    private String validarNivelClube(RequisicaoCheckout req) {
60	        if (req.nivelClube == null || NivelClube.fromString(req.nivelClube) == null) {
61	            return "NIVEL_CLUBE_INVALIDO";
62	        }
63	        return null;
64	    }
65	
66	    private String validarRegiao(RequisicaoCheckout req) {
67	        if (req.regiao == null || Regiao.fromString(req.regiao) == null) {
68	            return "REGIAO_INVALIDA";
69	        }
70	        return null;
71	    }
72	
73	    private String validarModalidadeEntrega(RequisicaoCheckout req, Double pesoTotal) {
74	        if (req.modalidadeEntrega == null || ModalidadeEntrega.fromString(req.modalidadeEntrega) == null) {
75	            return "MODALIDADE_INVALIDA";
76	        }
77	
78	        ModalidadeEntrega modalidade = ModalidadeEntrega.fromString(req.modalidadeEntrega);
79	        if (!modalidade.validaParaPedido(pesoTotal)) {
80	            return "MODALIDADE_INDISPONIVEL";
81	        }
82	
83	        return null;
84	    }
85	
86	    private String validarCupom(RequisicaoCheckout req, Double subtotal) {
87	        if (req.cupom == null) {
88	            return null;
89	        }
90	
91	        Cupom cupom = Cupom.fromString(req.cupom);
92	        if (cupom == null) {
93	            return "CUPOM_INVALIDO";
94	        }
95	
96	        if (!cupom.validaParaPedido(subtotal)) {
97	            return "CUPOM_NAO_APLICAVEL";
98	        }
99	
100	        return null;
101	    }
102	
103	    private String validarFormaPagamento(RequisicaoCheckout req) {
104	        if (req.formaPagamento == null || FormaPagamento.fromString(req.formaPagamento) == null) {
105	            return "FORMA_PAGAMENTO_INVALIDA";
106	        }
107	        return null;
108	    }
109	
110	    private String validarParcelamento(RequisicaoCheckout req) {
111	        FormaPagamento forma = FormaPagamento.fromString(req.formaPagamento);
112	        Integer parcelas = req.getParcelas();
113	
114	        if (!forma.validaParcelamento(parcelas)) {
115	            return "PARCELAMENTO_INVALIDO";
116	        }
117	
118	        return null;
119	    }
120	
121	    private String validarDisponibilidadeFormaPagamento(RequisicaoCheckout req) {
122	        Double subtotal = calcularSubtotal(req);
123	        Double pesoTotal = calcularPesoTotal(req);
124	        ModalidadeEntrega modalidade = ModalidadeEntrega.fromString(req.modalidadeEntrega);
125	        Double frete = modalidade.calcularFrete(pesoTotal);
126	        Regiao regiao = Regiao.fromString(req.regiao);
127	        Double seguro = regiao.calcularSeguro(subtotal);
128	
129	        Double totalBase = subtotal - (req.cupom != null ? Cupom.fromString(req.cupom).aplicarDesconto(subtotal, req.itens) : 0) + frete + seguro;
130	
131	        FormaPagamento forma = FormaPagamento.fromString(req.formaPagamento);
132	        if (!forma.validaParaPedido(totalBase)) {
133	            return "FORMA_PAGAMENTO_INDISPONIVEL";
134	        }
135	
136	        return null;
137	    }
138	
139	    private Double calcularSubtotal(RequisicaoCheckout req) {
140	        return req.itens.stream()
141	            .mapToDouble(ItemCarrinho::getValorTotal)
142	            .sum();
143	    }
144	
145	    private Double calcularPesoTotal(RequisicaoCheckout req) {
146	        return req.itens.stream()
147	            .mapToDouble(ItemCarrinho::getPesoTotal)
148	            .sum();
149	    }
150	}
